import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import crypto from 'node:crypto';
import {compactTag,transform,contentDigest,canShareStyle,registryFiles,slimPages} from '../build/slim_place_pages.mjs';
const css='.page{color:var(--ink);font:normal 16px/1.5 system-ui;margin:0 auto;max-width:70rem}.card{border:1px solid #ddd;padding:1rem}.table td{vertical-align:top;padding:8px}.chip{display:inline-block;border-radius:4px;background:#ffe;color:#234}@media(max-width:600px){.page{padding:12px}}';
const hash=s=>crypto.createHash('sha256').update(s).digest('hex');
const selected=new Map([[hash(css),{body:css,uses:20}]]);
for(const [input,want] of [[`<div class="foo" id='bar'>`,'<div class=foo id=bar>'],['<img src="/x.png"/>','<img src=/x.png />'],['<img alt="" src="/x.png">','<img alt="" src=/x.png>'],['<p title="a b" data-x="a=b">','<p title="a b" data-x="a=b">'],['<p data-x="a&amp;b" lang="de">','<p data-x=a&amp;b lang=de>'],['<p title="data-a=\'abc\'">','<p title="data-a=\'abc\'">']])test('safe attribute syntax '+input,()=>assert.equal(compactTag(input),want));
for(const value of ['a b','a\tb','a\nb','a\rb','a\fb','a"b',"a'b",'a`b','a<b','a>b','a=b',''])test('unsafe unquoted value retained '+JSON.stringify(value),()=>{const q=value.includes('"')?"'":'"';if(value.includes(q))return;const s='<p data-x='+q+value+q+'>';assert.equal(compactTag(s),s)});
for(const raw of ['script','style','textarea','title','xmp','iframe','noembed','noframes'])test('raw body preserved '+raw,()=>{const s='<'+raw+'><p class="quoted"> &  x\n</'+raw+'>';assert.equal(transform(s).html,s)});
test('plaintext remainder unchanged',()=>assert.equal(transform('<plaintext><p id="hi">').html,'<plaintext><p id="hi">'));
test('comments never rewritten',()=>assert.equal(transform('<!-- <a href="/x"> -->').html,'<!-- <a href="/x"> -->'));
test('JSON-LD remains byte-identical',()=>{const s='<script type="application/ld+json">{"name":"a <b> c","value":42}</script>';assert.ok(transform(s).html.endsWith('>{"name":"a <b> c","value":42}</script>'))});
test('unquoted and quoted attributes have same digest',()=>assert.equal(contentDigest('<a href="/x/" id="test">a  b</a>'),contentDigest('<a href=/x/ id=test>a  b</a>')));
test('text change affects content digest',()=>assert.notEqual(contentDigest('<p>x y</p>'),contentDigest('<p>xy</p>')));
test('style shared in same position without colour rewrite',()=>{const x=transform('<h1>A</h1><style>'+css+'</style><p>B</p>',selected);assert.equal(x.styleReplacements,1);assert.equal(x.html,'<h1>A</h1><link rel=stylesheet href=/assets/page-style/'+hash(css)+'.css><p>B</p>')});
for(const body of [css+'a{background:url(/x)}',css+'a{background:u\\72l(/x)}',css+'@import "x";',css+'a{background:image-set("x.png" 1x)}',css+'a{background:image("x.png")}',css+'/*# sourceMappingURL=x */',css+'@charset "utf-8";'])test('unsafe CSS base preserved '+body.slice(-40),()=>assert.equal(canShareStyle('<style>',body),false));
for(const start of ['<style id="x">','<style media="print">','<style nonce="x">','<style type="text/css">'])test('addressed style remains inline '+start,()=>assert.equal(canShareStyle(start,css),false));
for(const extra of ['<base href="/x/">','<meta http-equiv="Content-Security-Policy" content="style-src self">','<template>'])test('sensitive document skips extraction '+extra,()=>assert.equal(transform(extra+'<style>'+css+'</style>',selected).styleReplacements,0));
test('registry excludes startup shell',()=>assert.deepEqual(registryFiles([{path:'/'},{path:'/a/'}]),['a/index.html']));
for(const p of ['https://x/','//x/','/a/?b=x','/a/#x','/a/%2e/'])test('reject route '+p,()=>assert.throws(()=>registryFiles([{path:p}])));
function setup(){const root=fs.mkdtempSync(path.join(os.tmpdir(),'nz-slim-'));const reg=[];for(let i=0;i<12;i++){let rel='p'+i;fs.mkdirSync(path.join(root,rel));fs.writeFileSync(path.join(root,rel,'index.html'),'<!doctype html><html lang="en"><head><style>'+css+'</style></head><body><main id="main"><h1>Place '+i+'</h1><p class="text">Every fact remains.</p><a href="/p1/">Neighbour</a></main></body></html>');reg.push({path:'/'+rel+'/'});}return{root,reg};}
test('dry run leaves exact bytes unchanged and apply is repeat safe',()=>{const {root,reg}=setup();try{const p=path.join(root,'p0/index.html'),old=fs.readFileSync(p);const d=slimPages(root,reg);assert.equal(d.applied,false);assert.ok(d.netBytesSaved>0);assert.deepEqual(fs.readFileSync(p),old);const a=slimPages(root,reg,{apply:true});assert.equal(a.contentInvariantsPassed,12);assert.equal(a.newSharedAssets,1);const b=slimPages(root,reg,{apply:true});assert.equal(b.changedPages,0);assert.equal(b.netBytesSaved,0);}finally{fs.rmSync(root,{recursive:true,force:true})}});
test('symlink rejected before output changes',()=>{const{root,reg}=setup();try{const p=path.join(root,'p0/index.html');fs.unlinkSync(p);fs.symlinkSync('/etc/passwd',p);assert.throws(()=>slimPages(root,reg,{apply:true}),/Symlink/);}finally{fs.rmSync(root,{recursive:true,force:true})}});
test('traversal rejected',()=>{const{root}=setup();try{assert.throws(()=>slimPages(root,[{path:'/../outside/'}]),/Unsafe/)}finally{fs.rmSync(root,{recursive:true,force:true})}});
test('missing generated page fails closed',()=>{const{root}=setup();try{assert.throws(()=>slimPages(root,[{path:'/missing/'}]),/Missing/)}finally{fs.rmSync(root,{recursive:true,force:true})}});
test('conflicting shared asset fails before any page write',()=>{const{root,reg}=setup();try{const dir=path.join(root,'assets/page-style');fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,hash(css)+'.css'),'wrong');assert.throws(()=>slimPages(root,reg,{apply:true}),/conflict/);assert.ok(fs.readFileSync(path.join(root,'p0/index.html'),'utf8').includes('<style>'))}finally{fs.rmSync(root,{recursive:true,force:true})}});
